function invalidate(){if(report){$('results').hidden=true;$('welcome').hidden=false;$('welcome').querySelector('h2').textContent='Inputs changed. Build a fresh comparison.'}}
function input(side){const type=inputTypes[side];const previewStyles=$(side+'-cdn-css').value.trim().split(/\s+/).filter(Boolean),runtime=$(side+'-cdn-js').value.trim(),previewRuntimes=runtime?[{url:runtime,type:$(side+'-cdn-type').value}]:[];if(type==='library')return {localProfileId:$(side+'-library').value,previewStyles,previewRuntimes};const consent=scanPermissions[side]?.url===$(side+'-url').value.trim()?scanPermissions[side].flags:{};return {...consent,includeExamples:true,previewStyles,previewRuntimes,url:type==='code'?'':$(side+'-url').value.trim(),code:type==='link'?'':$(side+'-code').value.trim()}}
function progress(message){const line=document.createElement('div');line.textContent='✓ '+message;$('progress-log').append(line);$('progress-log').scrollTop=$('progress-log').scrollHeight;$('progress-title').textContent=message;const lower=String(message).toLowerCase(),phase=/comparing|step 3|compared|mapping/.test(lower)?'compare':/filter|retained|implementation elements|step 2/.test(lower)?'filter':'collect',order=['collect','filter','compare'],index=order.indexOf(phase);document.querySelectorAll('[data-progress-phase]').forEach((item,i)=>{item.classList.toggle('active',i===index);item.classList.toggle('complete',i<index)});const meter=$('progress-meter-fill'),bar=$('scan-progress')?.querySelector('.progress-meter');if(meter)meter.style.width=(index===0?'28%':index===1?'62%':'90%');if(bar)bar.setAttribute('aria-valuenow',index===0?'28':index===1?'62':'90');const subtitle=$('progress-subtitle');if(subtitle)subtitle.textContent=phase==='collect'?'Reading the selected pages and implementation sources.':phase==='filter'?'Separating components, tokens, examples and supporting content.':'Comparing capabilities and preparing the evidence trail.'}
async function scan(){if(!scenario)return;showWorkspacePage('new');const provider=$('extraction-provider')?.value||'deterministic';const firecrawlKey=$('firecrawl-api-key')?.value.trim()||'';const old=input('old'),target=input('new');old.extractionProvider=provider;target.extractionProvider=provider;$('input-error').hidden=true;$('scan-recovery').hidden=true;pendingRecovery=null;for(const [name,entry] of [['Current',old],['Target',target]]){if(!entry.url&&!entry.code&&!entry.localProfileId){$('input-error').textContent=`${name} design system needs a link or code.`;$('input-error').hidden=false;return}if(entry.url){const field=$(name==='Current'?'old-url':'new-url');if(!field.checkValidity()){field.reportValidity();return}}}controller=new AbortController();setBusy(true);$('results').hidden=true;$('welcome').hidden=true;$('scan-progress').hidden=false;$('progress-log').replaceChildren();progress('Starting collection…');try{if(old.localProfileId||target.localProfileId){for(const [side,entry]of [['old',old],['new',target]])if(entry.url){const profile=await importRemoteLibrary(entry,side,+$('page-budget').value);entry.localProfileId=profile.id;entry.url='';entry.code='';chooseInput(side,'library');$(side+'-library').value=profile.id;}report=await localComparison(old,target,scenario);excluded=new Set();edited={};activeCategory='All';limit=36;renderReport();$('results').scrollIntoView({behavior:'instant'});toast(report.comparisonReady===false?'Local report is available with partial evidence.':'Local comparison complete. No source files were uploaded.');return}const response=await fetch('/api/scan',{method:'POST',headers:{'Content-Type':'application/json',...(firecrawlKey?{'X-GapScan-Firecrawl-Key':firecrawlKey}:{})},body:JSON.stringify({scenario,old,new:target,budget:+$('page-budget').value,extractionProvider:provider}),signal:controller.signal});if(!response.ok){let error;try{error=(await response.json()).error}catch{error=`Scan failed (HTTP ${response.status}).`}throw new Error(error)}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',complete=false;const consume=line=>{if(!line.trim())return;const event=JSON.parse(line);if(event.type==='progress')progress(event.message);if(event.type==='error'){pendingRecovery={code:event.code,details:event.confirmation};if(['input_data_required','confirmation_required','website_unavailable'].includes(event.code)){$('scan-recovery').hidden=false;$('authorize-scan-recovery').hidden=event.code!=='confirmation_required';$('authorize-scan-recovery').textContent=event.confirmation?.action==='derive_website'?'Yes, extract & save this website’s design system':'Allow live scan'}throw new Error(event.message)};if(event.type==='result'){report=event.report;complete=true}};while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();lines.forEach(consume)}buffer+=decoder.decode();if(buffer.trim())consume(buffer);if(!complete)throw new Error('The connection ended before a complete report arrived. Retry the scan.');report=(await localEngine()).hydrateReport(report);excluded=new Set();edited={};activeCategory='All';limit=36;renderReport();$('results').scrollIntoView({behavior:'instant',block:'start'});toast(report.analysisIncomplete?'Partial report ready. Additional packages or uploads are optional.':'Comparison complete. Every result includes source evidence.')}catch(error){$('welcome').hidden=false;if(error.name==='AbortError')toast('Scan cancelled. Your inputs are still here.');else{$('input-error').textContent=error.message;$('input-error').hidden=false}}finally{setBusy(false);$('scan-progress').hidden=true;controller=null}}
function setBusy(busy){$('run-button').disabled=busy;document.querySelectorAll('[data-scenario],[data-side],#new-button,#demo-button,input[type=file],#old-code,#new-code,#old-url,#new-url,#page-budget,#firecrawl-api-key').forEach(el=>el.disabled=busy)}
function renderReport(){previewFrames.clear();$('results').hidden=false;$('welcome').hidden=true;$('scenario-label').textContent=report.migrationDetection?.label||(report.scenario==='upgrade'?'Version upgrade':report.scenario==='switch'?'Framework switch':'Comparison type not identified');$('scenario-label').title=(report.migrationDetection?.basis||[]).join(' · ');$('comparison-system-pair').replaceChildren();for(const [side,label]of [['old','A · Source — what you use today'],['new','B · Target — where you want to go']]){const system=document.createElement('div'),caption=document.createElement('span'),name=document.createElement('strong');caption.textContent=label;name.textContent=(report.savedLibraries?.[side]?.name||report.coverage[side].input)+(report.savedLibraries?.[side]?.version?' · '+report.savedLibraries[side].version:'');system.append(caption,name);$('comparison-system-pair').append(system)}$('inventory-count').textContent=report.summary.total;$('inventory-detail').textContent=`${report.summary.oldItems} current · ${report.summary.newItems} target`;$('change-count').textContent=report.summary.changed;$('source-count').textContent=report.summary.unverified||0;$('matched-count').textContent=report.items.filter(item=>item.old&&item.new).length;$('coverage-details').replaceChildren();for(const key of ['old','new']){const cov=report.coverage[key];const div=document.createElement('div');div.className='coverage-side';const h=document.createElement('h3');h.textContent=key==='old'?'A · Current design system':'B · Target design system';const label=document.createElement('p');label.textContent=cov.input;const p=document.createElement('p');p.textContent=`${cov.fetched} pages/files read${cov.pasted?' + pasted code':''} · ${cov.discovered} discovered · ${cov.failed.length} fetch errors · ${num(cov.bytes/1000)} KB`;div.append(h,label,p);for(const pkg of report.packages?.[key]||[]){const p=document.createElement('p');p.textContent=`npm: ${pkg.name}@${pkg.version} · ${pkg.filesRead} published files · ${pkg.basis}`;div.append(p)}for(const warning of cov.warnings){const w=document.createElement('p');w.className='warning';w.textContent=warning;div.append(w)}const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='View source ledger';details.append(summary);for(const doc of report.sources[key]){const p=document.createElement('p');p.textContent=doc;details.append(p)}for(const fail of cov.failed){const p=document.createElement('p');p.className='warning';p.textContent=fail.url+' — '+fail.error;details.append(p)}div.append(details);$('coverage-details').append(div)}$('report-notes').replaceChildren(...report.notes.map(note=>{const li=document.createElement('li');li.textContent=note;return li}));$('source-tab-count').textContent=report.extractions.old.length;$('target-tab-count').textContent=report.extractions.new.length;$('kind-filter').value=report.items.some(item=>item.old?.html||item.new?.html)?'visual':'All';extractionLimits={source:36,target:36};for(const [side,key] of [['source','old'],['target','new']])$(side+'-extraction-kind').value=report.extractions[key].some(item=>item.html)?'renderable':'All';for(const side of ['source','target']){const select=$(side+'-extraction-category');select.innerHTML='<option value="All">All categories</option>';for(const cat of report.domains){const option=document.createElement('option');option.value=cat;option.textContent=cat;select.append(option)}}$('comparison-paused-details').replaceChildren();$('coverage-status-title').textContent=report.savedLibraryComparison?'Saved libraries ready · no uploads required':'Partial report · continue with available evidence';$('coverage-status-copy').textContent=report.savedLibraryComparison?'All saved items, examples, tokens and preview assets are loaded for both systems. Original import limits and unresolved facts remain available in the evidence ledger.':'Some sources could not be read or were outside this scan budget. Matched items remain comparable. Unmatched or unresolved items are Unverified and receive no automatic effort. Additional evidence is optional.';$('coverage-files').hidden=!!report.savedLibraryComparison; if(report.savedLibraryComparison){for(const [key,label]of [['old','Source'],['new','Target']]){const saved=report.savedLibraries[key],row=document.createElement('p');row.textContent=label+': '+saved.name+(saved.version?' · '+saved.version:'')+' · '+saved.items+' saved items loaded · '+saved.counts.variants+' variants · '+saved.counts.tokens+' tokens · '+saved.counts.icons+' icons';$('comparison-paused-details').append(row)}}else if(report.analysisIncomplete){for(const [key,label]of [['old','Source'],['new','Target']]){const audit=report.extractionAudit?.[key];const row=document.createElement('p');row.textContent=label+': '+(audit?.complete?'Discovered sources processed':(audit?.issues.length||0)+' coverage issues · '+(report.coverage[key].pending?.length||0)+' unscanned sources');$('comparison-paused-details').append(row)}}renderRelevance();renderDeliverables();setReportTab('comparison');renderCategories();renderCards();updateTotals();prepareMappingResolution().catch(error=>toast(error.message))}
