function renderRelevance(){const audit=report.relevance,raw=audit.old.rawItems+audit.new.rawItems,removed=audit.old.excludedItems+audit.new.excludedItems,kept=audit.old.retainedItems+audit.new.retainedItems,cleaned=audit.old.cleanedItems+audit.new.cleanedItems;$('filter-funnel').innerHTML=`<div class="funnel-step"><strong>${raw}</strong><div>Discovered identifiers<small>Across both systems</small></div></div><span class="funnel-arrow">→</span><div class="funnel-step"><strong>${removed}</strong><div>Supporting identifiers<small>Removed from comparison</small></div></div><span class="funnel-arrow">→</span><div class="funnel-step final"><strong>${kept}</strong><div>Implementation identifiers<small>Ready for comparison</small></div></div>`;$('excluded-count').textContent=`(${removed} removed · ${cleaned} cleaned)`;auditLimit=30;renderAudit()}
function renderAudit(){if(!report)return;const query=$('exclusion-search').value.toLowerCase().trim(),side=$('exclusion-side').value;const records=['old','new'].flatMap(key=>report.relevance[key].excluded.map(item=>({...item,side:key}))).filter(item=>(side==='All'||item.side===side)&&(!query||`${item.name} ${item.reasons.join(' ')} ${item.evidence.map(e=>e.source).join(' ')}`.toLowerCase().includes(query)));$('excluded-list').replaceChildren();for(const record of records.slice(0,auditLimit)){const row=document.createElement('div');row.className='excluded-record';const title=document.createElement('div'),name=document.createElement('strong'),source=document.createElement('small');name.textContent=record.name;source.textContent=(record.side==='old'?'Current':'Target')+' · '+record.kind+' · '+(record.evidence[0]?.source||'');title.append(name,source);const reason=document.createElement('p');reason.textContent=record.reasons.join('; ');const state=document.createElement('span');state.textContent=record.fullyExcluded?'Excluded from gaps and effort':'Supporting observation stripped; implementation retained';reason.append(state);row.append(title,reason);$('excluded-list').append(row)}if(!records.length){const p=document.createElement('p');p.className='chart-empty';p.textContent='No excluded content matches this view.';$('excluded-list').append(p)}$('excluded-more').hidden=records.length<=auditLimit;$('excluded-more').textContent=`Show more (${records.length-auditLimit} remaining)`}
const pendingBriefs=new WeakMap();
function loadBriefPrompt(brief){if(brief.prompt)return Promise.resolve(brief.prompt);if(pendingBriefs.has(brief))return pendingBriefs.get(brief);const item=report.items.find(item=>'deliverable-'+item.id===brief.id);const work=(async()=>{const response=await fetch('/api/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deliverable:item})});if(!response.ok)throw new Error('The brief could not be prepared. Open it again to retry.');const result=await response.json();if(!result.brief?.prompt)throw new Error('No brief was returned for this item.');brief.prompt=result.brief.prompt;return brief.prompt})();pendingBriefs.set(brief,work);work.catch(()=>pendingBriefs.delete(brief));return work}
function renderDeliverables(){const panel=$('deliverables-panel'),list=$('deliverables-list');if(!panel||!list)return;const briefs=report?.deliverables?.items||[];panel.hidden=!report;list.replaceChildren();$('deliverables-count').textContent=briefs.length+' brief'+(briefs.length===1?'':'s');if(!briefs.length){const empty=document.createElement('p');empty.className='chart-empty';empty.textContent='No migration deliverables were generated for this comparison.';list.append(empty);return}for(const brief of briefs.slice(0,80)){const details=document.createElement('details');details.className='deliverable-brief';const summary=document.createElement('summary');summary.textContent=brief.title+' · '+brief.category;const meta=document.createElement('p');meta.className='deliverable-meta';meta.textContent=`Apply in: ${brief.applyIn} · ${brief.stage} · ${brief.effort===null?'Effort: not estimated':`Effort: ${brief.effort} hours / app`}`;const status=document.createElement('span');status.className='pill '+(brief.canAssist?'blue':'neutral');status.textContent=brief.canAssist?'AI can draft':'Evidence review first';const prompt=document.createElement('pre');prompt.className='deliverable-prompt';prompt.textContent=brief.prompt||'Open this brief to prepare its prompt.';details.addEventListener('toggle',async()=>{if(!details.open||brief.prompt)return;prompt.textContent='Preparing the evidence-backed prompt…';try{prompt.textContent=await loadBriefPrompt(brief)}catch(error){prompt.textContent=error.message}});const copy=document.createElement('button');copy.type='button';copy.className='button secondary';copy.textContent='Copy brief';copy.onclick=async()=>{try{await navigator.clipboard.writeText(await loadBriefPrompt(brief));toast('Brief copied.')}catch(error){toast(error.message||'Copy is unavailable in this browser.')}};details.append(summary,meta,status,prompt,copy);list.append(details)}}
function renderAnalytics(){if(!report)return;const counts=STATUSES.map(status=>report.items.filter(i=>(i.reviewStatus||i.status)===status).length),total=report.items.length,paired=report.items.filter(i=>i.old&&i.new).length,coverage=report.mappingResolution?Math.round(report.mappingResolution.rows.filter(row=>row.sourceId&&row.status==='Confirmed').length/Math.max(1,report.mappingResolution.summary.sourceGroups)*100):report.summary.oldItems?Math.round(paired/report.summary.oldItems*100):null;const unresolved=counts[2],changed=counts[0]+counts[1];$('decision-title').textContent=report.savedLibraryComparison?'Comparison from saved libraries':report.analysisIncomplete?'Observed changes · partial evidence':unresolved?`${unresolved} source-only element${unresolved===1?'':'s'} need mapping review`:changed?`${changed} migration change${changed===1?'':'s'} to plan`:'No changed definitions in the matched inventory';const partial=Object.values(report.coverage).some(c=>c.failed.length||c.warnings.some(w=>/budget|unscanned|blocked|deadline|missing|not checked|could not/i.test(w)));$('decision-copy').textContent=report.savedLibraryComparison?`${changed} observed changes · ${counts[5]} mappings need review. Both saved inventories are fully loaded; no uploads are required. Estimates include verified matched changes only.`:report.analysisIncomplete?`${changed} observed changes can be reviewed now. ${counts[5]} items remain unverified. Estimates cover matched changes only; adding evidence is optional.`:`${changed} changed or renamed elements require consumer review. ${counts[3]} target additions can be evaluated for adoption. ${unresolved? 'Validate target coverage before selecting replacements. ':''}${partial?'The scan has coverage limits; fill evidence gaps before committing the plan.':'The findings describe the supplied and fetched inputs.'}`;if(report.mappingResolution){const mapping=report.mappingResolution.summary;$('decision-title').textContent=mapping.Suggested?'Your next step: review the suggested matches':mapping.Unresolved?'Your next step: resolve the remaining items':'Counterparts confirmed. Review changes and behavior.';$('decision-copy').textContent=mapping.Confirmed+' Confirmed · '+mapping.Suggested+' Suggested · '+mapping.Unresolved+' Unresolved groups. '+(mapping.Suggested?'Review suggested matches before planning changes. ':mapping.Unresolved?'Check coverage and alternatives for unresolved items. ':'')+'Confirmed matches still need behavior checks; estimates use supported item-level changes.';}$('match-rate').innerHTML=`<strong>${coverage===null?'—':coverage+'%'}</strong><span>${report.mappingResolution?'Source groups with a confirmed counterpart':'Current inventory with an observed target match'}</span>`;
let cursor=0;const segments=counts.map((count,index)=>{const from=cursor;cursor+=total?count/total*100:0;return `${STATUS_COLORS[index]} ${from}% ${cursor}%`});$('status-chart').replaceChildren();const donut=document.createElement('div');donut.className='donut';donut.style.background=total?`conic-gradient(${segments.join(',')})`:'#eef2f7';donut.setAttribute('role','img');donut.setAttribute('aria-label',STATUSES.map((s,i)=>`${counts[i]} ${s}`).join(', '));donut.innerHTML=`<div class="donut-center"><strong>${total}</strong><span>compared elements</span></div>`;const legend=document.createElement('div');legend.className='status-legend';STATUSES.forEach((status,index)=>{if(!counts[index])return;const button=document.createElement('button');button.className='legend-button';button.innerHTML=`<i class="status-dot" style="background:${STATUS_COLORS[index]}"></i><span>${status}</span><strong>${counts[index]}</strong><small>${total?Math.round(counts[index]/total*100):0}%</small>`;button.setAttribute('aria-label',`Inspect ${status}: ${counts[index]} elements`);button.addEventListener('click',()=>selectGap(status));legend.append(button)});$('status-chart').append(donut,legend);
$('domain-chart').replaceChildren();const domainCounts=report.domains.map(domain=>STATUSES.map(status=>report.items.filter(i=>i.category===domain&&(i.reviewStatus||i.status)===status).length)),max=Math.max(1,...domainCounts.map(a=>a.reduce((s,n)=>s+n,0)));report.domains.forEach((domain,index)=>{const data=domainCounts[index],sum=data.reduce((s,n)=>s+n,0),button=document.createElement('button');button.className='domain-row';button.setAttribute('aria-label',`${domain}: ${sum} compared elements`);const label=document.createElement('span');label.textContent=report.domains[index];const bar=document.createElement('span');bar.className='stack-bar';bar.style.background='transparent';data.forEach((count,i)=>{const segment=document.createElement('i');segment.style.width=(count/max*100)+'%';segment.style.background=STATUS_COLORS[i];segment.title=`${STATUSES[i]}: ${count}`;bar.append(segment)});const value=document.createElement('strong');value.textContent=sum;button.append(label,bar,value);button.addEventListener('click',()=>selectGap('All',domain));$('domain-chart').append(button)});
const effort=report.domains.map((domain,index)=>({domain,label:report.domains[index],hours:report.items.filter(i=>i.category===domain&&i.estimateAvailable!==false&&!excluded.has(i.id)).reduce((s,i)=>s+(edited[i.id]??i.hours),0)})).sort((a,b)=>b.hours-a.hours),maxHours=Math.max(1,...effort.map(e=>e.hours));$('effort-chart').replaceChildren();for(const entry of effort){const button=document.createElement('button');button.className='effort-row';button.setAttribute('aria-label',`${entry.domain}: ${num(entry.hours)} hours per app`);button.innerHTML=`<span>${entry.label}</span><span class="effort-bar"><i style="width:${entry.hours/maxHours*100}%"></i></span><strong>${num(entry.hours)} hrs</strong>`;button.addEventListener('click',()=>selectGap('All',entry.domain));$('effort-chart').append(button)}
const priorities=report.items.filter(i=>i.status!=='Unchanged'&&!excluded.has(i.id)).sort((a,b)=>{const score=i=>(i.insight?.priority==='P1'?10:0)+(i.status==='Source only'?6:['Changed','Renamed'].includes(i.status)?3:0)+(i.risk==='High'?3:i.risk==='Medium'?1:0);return score(b)-score(a)||(edited[b.id]??b.hours)-(edited[a.id]??a.hours)});$('priority-count').textContent=priorities.length;$('priority-list').replaceChildren();priorities.slice(0,5).forEach((item,index)=>{const button=document.createElement('button');button.className='priority-item';const rank=document.createElement('span');rank.className='priority-rank';rank.textContent=index+1;const title=document.createElement('div'),name=document.createElement('strong'),meta=document.createElement('small');name.textContent=item.canonicalLabel||item.name;meta.textContent=(item.reviewStatus||item.status)+' · '+item.risk+' risk';title.append(name,meta);const hours=document.createElement('span');hours.textContent=item.estimateAvailable===false?'Not estimated':num(edited[item.id]??item.hours)+' hrs';button.append(rank,title,hours);button.addEventListener('click',()=>selectGap('All',item.category,item.name));$('priority-list').append(button)});if(!priorities.length){const p=document.createElement('p');p.className='chart-empty';p.textContent='No changed or unmatched elements remain in the included estimate.';$('priority-list').append(p)}}

let extractionLimits={source:36,target:36};
