function initReportNavigation(){const index=$('report-section-index');if(!index)return;const buttons=[...index.querySelectorAll('[data-index-target]')];const setActive=id=>buttons.forEach(button=>button.classList.toggle('active',button.dataset.indexTarget===id));for(const button of buttons)button.addEventListener('click',()=>{const target=$(button.dataset.indexTarget);if(!target)return;const page=button.dataset.indexTarget==='panel-source'?'source':button.dataset.indexTarget==='panel-target'?'target':button.dataset.indexTarget==='panel-evidence'?'evidence':button.dataset.indexTarget==='panel-estimate'?'estimate':'comparison';setReportTab(page);for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'}));setActive(button.dataset.indexTarget)});if('IntersectionObserver'in window){const targets=buttons.map(button=>$(button.dataset.indexTarget)).filter(Boolean);const observer=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)setActive(visible.target.id)},{rootMargin:'-118px 0px -58% 0px',threshold:[0,.15,.5]});targets.forEach(target=>observer.observe(target))}}
