function filtered(){const query=$('search').value.trim().toLowerCase(),status=$('status-filter').value,kind=$('kind-filter').value;return report.items.filter(item=>(kind==='All'||kind==='visual'&&(item.old?.html||item.new?.html)||kind===item.kind)&&(activeCategory==='All'||activeCategory===item.category)&&(status==='All'||status===item.status||status===item.presenceStatus||status===item.resolutionStatus)&&(!query||`${item.name} ${item.new?.name||''} ${item.action} ${item.old?.value||''} ${item.new?.value||''}`.toLowerCase().includes(query)))}
function renderCategories(){$('categories').replaceChildren();for(const cat of ['All',...report.domains]){const count=cat==='All'?report.items.length:report.items.filter(i=>i.category===cat).length;const button=document.createElement('button');button.className='category-button'+(activeCategory===cat?' active':'');button.setAttribute('aria-pressed',activeCategory===cat);button.append(document.createTextNode(cat==='All'?'All extracted elements':cat));const badge=document.createElement('span');badge.textContent=count;button.append(badge);button.addEventListener('click',()=>{activeCategory=cat;limit=36;renderCategories();renderCards()});$('categories').append(button)}}
function specimenFrame(item,label,state='default'){return originalFrame(item,label,state)}
function addSpecimenDetails(side,item,label){if(!item)return;const props=item.styleProfile?.default||{};const palette=[...new Set(['color','background-color','background','border-color'].map(p=>props[p]).filter(v=>v&&/^(?:#[\da-f]{3,8}|rgba?\(|hsla?\(|red$|blue$|green$|black$|white$)/i.test(v)))];if(palette.length){const colors=document.createElement('div');colors.className='component-palette';palette.forEach(value=>{const chip=document.createElement('span');const dot=document.createElement('i');dot.style.background=value;chip.append(dot,document.createTextNode(value));colors.append(chip)});side.append(colors)}const typography=Object.entries(props).filter(([key])=>/font|line-height|letter-spacing/.test(key));if(typography.length){const text=document.createElement('div');text.className='component-type';text.textContent=typography.map(([key,value])=>key+': '+value).join(' · ');side.append(text)}
const states=Object.keys(item.styleProfile||{}).filter(s=>s!=='default');if(states.length){const details=document.createElement('details');details.className='state-examples';const summary=document.createElement('summary');summary.textContent='Observed state specimens ('+states.length+')';details.append(summary);const grid=document.createElement('div');grid.className='state-grid';for(const state of states){const box=document.createElement('div'),title=document.createElement('span');title.textContent=state;box.append(title);const frame=specimenFrame(item,label,state);if(frame)box.append(frame);grid.append(box)}details.append(grid);side.append(details)}}
function insightPanel(item){const panel=document.createElement('details');panel.className='actionable-insight';const summary=document.createElement('summary');summary.textContent=(item.insight?.priority||'Review')+' · Changes, actions & validation';panel.append(summary);if(!item.insight)return panel;const list=document.createElement('div');list.className='delta-list';for(const delta of item.insight.differences){const row=document.createElement('div');row.innerHTML=`<strong>${esc(delta.property)} <small>${esc(delta.state)}</small></strong><span>${esc(delta.before??'Not observed')}</span><b>→</b><span>${esc(delta.after??'Not observed')}</span>`;list.append(row)}panel.append(list);for(const [title,values]of [['Migration actions',item.insight.actions],['Validation checks',item.insight.validation]]){const h=document.createElement('h4');h.textContent=title;const ul=document.createElement('ul');for(const text of values){const li=document.createElement('li');li.textContent=text;ul.append(li)}panel.append(h,ul)}if(item.insight.unverifiedStates.length){const p=document.createElement('p');p.textContent='Not verified on both sides: '+item.insight.unverifiedStates.join(', ')+'.';panel.append(p)}return panel}
function renderComparisonTable(){if(!report||$('comparison-view').value!=='table')return;const group=$('table-group').value,rows=filtered().filter(i=>group==='All'||(i.old||i.new).visualFamily===group);$('comparison-table-body').replaceChildren();for(const item of rows.slice(0,limit)){const tr=document.createElement('tr');const name=document.createElement('td');name.innerHTML=`<strong>${esc(item.canonicalLabel||item.name)}</strong><small>${esc(item.name)}${item.new&&item.old?.name!==item.new.name?' → '+esc(item.new.name):''}</small><small>${esc(item.category)}</small>`;const family=document.createElement('td');family.textContent=(item.old||item.new).visualFamily||'Components';const old=document.createElement('td'),target=document.createElement('td');for(const pair of pairPreviewVariants(item.old,item.new)){old.append(makeVariantPreview(pair.old,'SOURCE',pair.label));target.append(makeVariantPreview(pair.new,'TARGET',pair.label));}const change=document.createElement('td');change.append(document.createTextNode(item.reviewStatus||item.presenceStatus||item.status),migrationPlanningPanel(item),insightPanel(item));tr.append(name,family,old,target,change);$('comparison-table-body').append(tr)}$('table-count').textContent=Math.min(limit,rows.length)+' / '+rows.length+' compared items';$('table-more').hidden=rows.length<=limit}

function makeSinglePreview(item,label){const side=document.createElement('div');side.className='preview-side';const heading=document.createElement('div');heading.className='preview-label';heading.textContent=label;const box=document.createElement('div');box.className='preview-box';const kind=document.createElement('span');kind.className='preview-kind';if(!item){box.textContent=/CURRENT|SOURCE/.test(label)?'Not found in source':'Not found in target';kind.textContent='No counterpart identified in this scan · removal not inferred'}else if(['token','foundation'].includes(item.kind)){let value=(item.examples?.value||item.value).trim();try{const parsed=JSON.parse(value);if(typeof parsed==='string')value=parsed}catch{}if(item.examples?.colorCss)value=item.examples.colorCss;if(!/var\(|\{[^}]+\}/.test(value)&&CSS.supports('color',value)){const swatch=document.createElement('div');swatch.className='token-swatch';swatch.style.background=value.replace(/\s*!important$/i,'');const text=document.createElement('div');text.className='token-value';text.textContent=value;box.append(swatch,text)}else if(item.visualFamily==='Typography'){const props=item.examples?.typography||{[/family|typeface/i.test(item.name+' '+(item.tokenType||''))?'fontFamily':/weight/i.test(item.name+' '+(item.tokenType||''))?'fontWeight':/line.?height/i.test(item.name+' '+(item.tokenType||''))?'lineHeight':/letter/.test(item.name)?'letterSpacing':'fontSize']:value};const css=Object.entries(props).map(([key,val])=>key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+':'+val).join(';');box.append(originalFrame({...item,html:'<p style="'+esc(css)+'">Aa · The quick brown fox</p>'},label));}else{const pre=document.createElement('pre');pre.textContent=value;box.append(pre)}kind.textContent=item.kind==='token'?'Extracted token value':'Observed foundation style'}else{const frame=originalFrame(item,label,'default',(message,error)=>{kind.textContent=(item.glyph?'CSS glyph · ':'')+message;kind.classList.toggle('preview-warning',!!error)});if(frame){box.append(frame);kind.textContent='Original retrieved example';}else{box.innerHTML='<div class="absent">Runnable example was not published in the retrieved files.<br>View its definition or optionally add a documented example.</div>';if(item.documentationUrl){const link=document.createElement('a');link.className='button secondary';link.href=item.documentationUrl;link.target='_blank';link.rel='noopener noreferrer';link.textContent='View component example ↗';box.append(link)}kind.textContent=item.css?'Styles retrieved · no runnable markup in this sample':'Definition retrieved · no runnable example in this sample';kind.classList.add('preview-warning')}}side.append(heading,box,kind);if(item?.referenceImage&&/^data:image\/(?:png|jpeg|webp);base64,/.test(item.referenceImage)){const visual=document.createElement('img');visual.src=item.referenceImage;visual.alt='Attached visual reference for '+item.name;visual.className='attached-reference-image';const caption=document.createElement('small');caption.textContent='User-supplied visual reference · implementation and states unverified';side.append(visual,caption)}if(item?.kind==='token'&&item.values?.length>1){const select=document.createElement('select');select.className='variant-select';select.setAttribute('aria-label',label+' '+item.name+' token definition');item.values.forEach((value,index)=>{const option=document.createElement('option');option.value=index;option.textContent=(item.tokenDefinitions?.find(d=>d.value===value)?.scope||'Declared value '+(index+1))+' · '+value.slice(0,60);select.append(option)});select.onchange=async()=>{const value=item.values[+select.value],key=/CURRENT|SOURCE/.test(label)?'old':'new';try{const engine=await import('/local-engine.js');const inventory={items:(label==='LIBRARY'?libraryViewer.items:report.extractions[key]).filter(i=>i.kind==='token').map(i=>i.id===item.id?{...i,value,values:[value]}:{...i})};engine.enrichExamples(inventory);const updated=makePreview(inventory.items.find(i=>i.id===item.id),label);box.replaceChildren(...updated.querySelector('.preview-box').childNodes)}catch(error){toast(error.message)}};side.insertBefore(select,box)}addSpecimenDetails(side,item,label);if(item?.documentationUrl){const link=document.createElement('a');link.href=item.documentationUrl;link.target='_blank';link.rel='noopener noreferrer';link.className='component-doc-link';link.textContent='Open component documentation section ↗';side.append(link)}return side}
function makeCard(item,interactive=true){const article=document.createElement('article');article.className='comparison-card'+(excluded.has(item.id)?' excluded':'');const heading=document.createElement('div');heading.className='card-heading';const title=document.createElement('div'),h=document.createElement('h3');h.textContent=item.canonicalLabel|| (item.old&&item.new&&item.old.name!==item.new.name?`${item.old.name} → ${item.new.name}`:item.name);h.title=h.textContent;const small=document.createElement('small');small.textContent=item.kind+' · '+item.category+' · '+item.name;title.append(h,small);const status=document.createElement('span');status.className='status '+item.status.toLowerCase().replace(/ /g,'-');status.textContent=item.reviewStatus||item.presenceStatus||item.status;status.title=item.resolutionAction||item.presenceNote||item.confidence;heading.append(title,status);const previews=makeComparisonPreviews(item.old,item.new);const meta=document.createElement('div');meta.className='card-meta';const risk=document.createElement('span');risk.className='risk '+item.risk.toLowerCase();risk.textContent=item.risk+' risk';const tier=document.createElement('span');tier.className='badge '+({1:'simple',2:'simple',3:'moderate',4:'complex',5:'paradigm'}[item.effortLevel]||'simple');tier.textContent=item.tier;const effort=document.createElement('label');effort.append(document.createTextNode('Hours / app'));const number=document.createElement('input');number.type='number';number.min=0;number.max=1000;number.step=.5;number.value=edited[item.id]??item.hours;number.setAttribute('value',number.value);number.setAttribute('aria-label',item.name+' hours per application');number.disabled=!interactive||item.estimateAvailable===false;number.addEventListener('input',()=>{const value=number.valueAsNumber;if(Number.isFinite(value)&&value>=0&&value<=1000){edited[item.id]=value;updateTotals()}});number.addEventListener('change',()=>{const value=number.valueAsNumber;if(!Number.isFinite(value)||value<0||value>1000){number.value=edited[item.id]??item.hours;toast('Enter hours between 0 and 1,000.');return}edited[item.id]=value;updateTotals()});effort.append(number);meta.append(risk,tier,effort);const action=document.createElement('p');action.className='card-action';action.textContent=item.resolutionAction?item.resolutionAction+' Observed change: '+item.action:item.action;const scope=document.createElement('label');scope.className='scope-check';const check=document.createElement('input');check.type='checkbox';check.checked=item.estimateAvailable!==false&&!excluded.has(item.id);if(check.checked)check.setAttribute('checked','');check.disabled=!interactive||item.estimateAvailable===false;check.setAttribute('aria-label','Include '+item.name);check.addEventListener('change',()=>{if(check.checked)excluded.delete(item.id);else excluded.add(item.id);article.classList.toggle('excluded',!check.checked);updateTotals()});scope.append(check,document.createTextNode('Include in observed-change estimate'));const match=document.createElement('p');match.className='match-note';match.textContent=item.match+' · '+item.confidence;const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='View extraction evidence';details.append(summary);for(const [label,source]of [['Current',item.old],['Target',item.new]])if(source){for(const ev of source.evidence){const div=document.createElement('div');div.className='evidence';const strong=document.createElement('strong');strong.textContent=label+' · '+source.confidence;const link=document.createElement(ev.sectionUrl?'a':'span');link.textContent=ev.sectionUrl?'Open component documentation section ↗':'Extracted code evidence · line '+ev.line;if(link.tagName==='A'){link.href=ev.sectionUrl;link.target='_blank';link.rel='noopener noreferrer'}const pre=document.createElement('pre');pre.textContent=ev.snippet;div.append(strong,link,pre);details.append(div)}}article.append(heading,previews,migrationPlanningPanel(item),meta,action,insightPanel(item),scope,match,details);return article}
function renderCards(){renderCategoryTree('comparison');renderComparisonTable();const items=filtered();$('comparison-grid').replaceChildren();if($('comparison-view').value==='cards')for(const item of items.slice(0,limit))$('comparison-grid').append(makeCard(item));$('visible-count').textContent=`${Math.min(limit,items.length)} / ${items.length}`;;if($('comparison-results-count'))$('comparison-results-count').textContent=Math.min(limit,items.length)+' visible · '+items.length+' total';$('empty-state').hidden=items.length>0;if(items.length>limit){const more=document.createElement('button');more.className='button secondary load-more';more.textContent=`Show more (${items.length-limit} remaining)`;more.addEventListener('click',()=>{limit+=36;renderCards()});$('comparison-grid').append(more)}applyPlainLanguage()}
// Totals come only from the engine's migrationBriefTotals (engine/estimate.mjs) via
// decisionCalculatorTotals. Until it is ready the estimate reads Not estimated
// instead of falling back to a second, differently summed calculation.
function getTotals(){const planned=typeof decisionCalculatorTotals==='function'?decisionCalculatorTotals():null;if(planned)return planned;return {available:false,pending:true,baseline:0,hours:0,buffered:0,weeks:0,budget:0,included:0}}
const weeksText=value=>value>0&&value<0.1?'<0.1':num(value);
function totalRange(totals,key,format=key==='weeks'?weeksText:num){if(!totals.available)return 'Not estimated';const range=totals.range?.[key];if(!range)return format(totals[key]);const low=format(range.low),high=format(range.high);return low===high?low:low+'–'+high}
const num=v=>v.toLocaleString('en-US',{maximumFractionDigits:1});const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
function updateTotals(){if(!report)return;const totals=getTotals(),suffix=text=>totals.available?text:'';$('base-hours').textContent=totalRange(totals,'baseline')+suffix(' hrs');$('weeks').textContent=totalRange(totals,'weeks');$('hours').textContent=totalRange(totals,'hours')+suffix(' hrs');$('buffered').textContent=totalRange(totals,'buffered')+suffix(' hrs');$('budget').textContent=totalRange(totals,'budget',money);$('rate-label').textContent='$'+$('rate').value+' / hr';$('apps-label').textContent=$('apps').value+' app(s)';$('team-label').textContent=$('team').value+' engineer(s)';$('buffer-label').textContent=$('buffer').value+'%';renderAnalytics();applyPlainLanguage()}
function exportData(){return {...report,analysis:{statusCounts:Object.fromEntries(STATUSES.map(s=>[s,report.items.filter(i=>i.status===s).length])),domains:report.domains.map(domain=>({domain,count:report.items.filter(i=>i.category===domain).length,hours:report.items.filter(i=>i.category===domain&&i.estimateAvailable!==false&&!excluded.has(i.id)).reduce((sum,i)=>sum+(edited[i.id]??i.hours),0)}))},items:report.items.map(i=>({...i,hours:edited[i.id]??i.hours,included:i.estimateAvailable!==false&&!excluded.has(i.id)})),assumptions:{rate:+$('rate').value,apps:+$('apps').value,team:+$('team').value,buffer:+$('buffer').value,productiveHours:35,currency:'USD'},totals:getTotals()}}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report exported.')}
function markdown(){const r=exportData(),lines=['# GapScan technical gap specification','',`Generated: ${r.createdAt}`,`Migration: ${r.scenario}`,`Engine: ${r.engine}`,'','## Coverage'];for(const [key,c]of Object.entries(r.coverage))lines.push(`- ${key}: ${c.input}; ${c.fetched} pages/files fetched; ${c.discovered} discovered; ${c.failed.length} failures.`,...c.warnings.map(w=>'- Warning: '+w));lines.push('','## Relevance filter',`- Current: ${r.relevance.old.rawItems} discovered, ${r.relevance.old.excludedItems} excluded, ${r.relevance.old.retainedItems} retained.`,`- Target: ${r.relevance.new.rawItems} discovered, ${r.relevance.new.excludedItems} excluded, ${r.relevance.new.retainedItems} retained.`,'','## Extraction inventories',`- Source: ${r.extractions.old.length} implementation elements.`,`- Target: ${r.extractions.new.length} implementation elements.`,'','## Gap distribution',...STATUSES.map(status=>`- ${status}: ${r.analysis.statusCounts[status]}`),'','## Estimate',`- Included: ${r.totals.included} / ${r.items.length}`,`- Baseline: ${totalRange(r.totals,'baseline')} hours per app`,`- Total with buffer: ${totalRange(r.totals,'buffered')} hours`,`- Timeline: ${totalRange(r.totals,'weeks')} weeks`,`- Budget: ${totalRange(r.totals,'budget',money)}`,`- Assumptions: ${JSON.stringify(r.assumptions)}`,'','## Interpretation',...r.notes.map(n=>'- '+n));for(const cat of r.domains){const items=r.items.filter(i=>i.category===cat);lines.push('','## '+cat);for(const i of items){lines.push('','### '+i.name,`- Status: ${i.status}; risk: ${i.risk}; effort: ${i.hours} hrs/app; included: ${i.included}`,`- Mapping: ${i.match}`,`- Action: ${i.action}`);for(const [label,item]of [['Current',i.old],['Target',i.new]])if(item){lines.push(`- ${label}: ${item.name}`,'```text',item.value.replace(/```/g,"'''"),'```',...item.evidence.map(e=>e.sectionUrl?`- Component section: [Open documentation](${e.sectionUrl}), line ${e.line}`:`- Extracted code evidence, line ${e.line}`))}}}return lines.join('\n')}
async function exportHtml(){const response=await fetch('/styles.css');if(!response.ok)throw new Error('Stylesheet unavailable');const css=(await response.text()).replace(/@import[^;]+;/,'');const runtimeResponse=await fetch('/preview-frame.js');if(!runtimeResponse.ok)throw new Error('Preview runtime unavailable');const runtimeCode=await runtimeResponse.text();const cards=report.items.map(i=>{const card=makeCard(i,false);exportPreviewHosts(card,runtimeCode);return card.outerHTML}).join('');const totals=getTotals();const dashboardMarkup=document.querySelector('#analytics').outerHTML+document.querySelector('.relevance-panel').outerHTML+document.querySelector('.decision-brief').outerHTML;const data=JSON.stringify(report.domains).replace(/</g,'\\u003c');download(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GapScan estimation report</title><style>${css}main{max-width:1300px;margin:auto;padding:25px}.comparison-grid{grid-template-columns:repeat(auto-fit,minmax(290px,1fr))}.report-filters{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.comparison-card[hidden]{display:none}h1{font-size:28px}</style></head><body><main><div class="eyebrow">GAPSCAN EVIDENCE ENGINE</div><h1>Design system migration report</h1><p>${esc(report.scenario)} · ${esc(report.createdAt)} · ${report.items.length} compared elements</p><p>Included baseline: ${totalRange(totals,'baseline')} hrs/app · Budget: ${totalRange(totals,'budget',money)} · Timeline: ${totalRange(totals,'weeks')} weeks</p><details><summary>Coverage and assumptions</summary><pre>${esc(JSON.stringify({coverage:report.coverage,assumptions:exportData().assumptions},null,2))}</pre></details><ul>${report.notes.map(n=>'<li>'+esc(n)+'</li>').join('')}</ul>${dashboardMarkup}<div id="filters" class="report-filters"></div><div class="comparison-grid">${cards}</div></main><script>const domains=${data};document.querySelectorAll('.analytics-grid button').forEach(b=>b.disabled=true);document.querySelector('.ledger-toolbar')?.remove();document.getElementById('excluded-more')?.remove();['All',...domains].forEach(c=>{const b=document.createElement('button');b.className='button secondary';b.textContent=c;b.onclick=()=>document.querySelectorAll('.comparison-card').forEach(card=>card.hidden=c!=='All'&&!card.querySelector('.card-heading small').textContent.endsWith(c));document.getElementById('filters').append(b)});<\/script></body></html>`,'estimation-report.html','text/html')}
for(const button of document.querySelectorAll('[data-scenario]'))button.addEventListener('click',()=>chooseScenario(button.dataset.scenario));for(const button of document.querySelectorAll('[data-side]'))button.addEventListener('click',()=>chooseInput(button.dataset.side,button.dataset.type));for(const side of ['old','new']){for(const name of ['url','code'])$(side+'-'+name).addEventListener('input',invalidate);$(side+'-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>300000){toast('Please use a source file smaller than 300 KB.');return}$(side+'-code').value=await file.text();invalidate();toast(file.name+' loaded.')})}
