// The comparison mode is inferred from the two inputs; the old mode cards are no longer part of the flow.
function inferComparisonMode(){const values=[$('old-url')?.value||$('old-code')?.value||'', $('new-url')?.value||$('new-code')?.value||''].map(value=>value.toLowerCase());const identity=value=>value.includes('bootstrap')?'bootstrap':value.includes('material')||value.includes('m3.')?'material':value.includes('fluent')?'fluent':value.includes('spectrum')?'spectrum':value.includes('blueprint')?'blueprint':value.includes('carbon')?'carbon':value.includes('polaris')?'polaris':value.includes('fui-')?'fluent':null;const [source,target]=values.map(identity);return source&&target?(source===target?'upgrade':'switch'):'auto'}
