function initExtractionSettings(){
 if($('extraction-settings-dialog'))return;
 const dialog=document.createElement('dialog');
 dialog.id='extraction-settings-dialog';
 dialog.className='save-dialog extraction-settings-dialog';
 dialog.innerHTML=`<div class="dialog-header"><div><span class="eyebrow">EXTRACTION SETTINGS</span><h2>Choose how GapScan reads this input</h2></div><button id="extraction-settings-close" class="text-button" type="button" aria-label="Close extraction settings">×</button></div><p class="extraction-settings-copy">Use the built-in engine for predictable evidence, or Firecrawl for JavaScript-heavy and hard-to-reach websites.</p><div class="field"><label for="extraction-settings-engine">EXTRACTION ENGINE</label><select id="extraction-settings-engine"><option value="deterministic">GapScan engine · predictable evidence</option><option value="firecrawl">Firecrawl · resilient website extraction</option></select></div><div class="field"><label for="extraction-settings-key">FIRECRAWL API KEY · THIS SESSION</label><input id="extraction-settings-key" type="password" autocomplete="off" spellcheck="false" placeholder="Optional fc-…"><small>Only used for this browser session. It is never saved to your design-system library.</small></div><p id="extraction-settings-status" role="status"></p><div class="dialog-actions"><button id="extraction-settings-cancel" class="button secondary" type="button">Cancel</button><button id="extraction-settings-save" class="button primary" type="button">Use this engine</button></div>`;
 document.body.append(dialog);
 const sync=()=>{const provider=$('extraction-provider'),key=$('firecrawl-api-key');$('extraction-settings-engine').value=provider?.value||'deterministic';$('extraction-settings-key').value=key?.value||''};
 const close=()=>dialog.close();
 document.addEventListener('click',event=>{const trigger=event.target.closest('[data-extraction-settings]');if(!trigger)return;sync();dialog.dataset.side=trigger.dataset.extractionSettings||'';dialog.showModal()});
 $('extraction-settings-save').addEventListener('click',()=>{const provider=$('extraction-provider'),key=$('firecrawl-api-key');if(provider)provider.value=$('extraction-settings-engine').value;if(key)key.value=$('extraction-settings-key').value.trim();$('extraction-settings-status').textContent=`Using ${$('extraction-settings-engine').selectedOptions[0].textContent}.`;toast('Extraction settings updated.');setTimeout(close,180)});
 $('extraction-settings-cancel').addEventListener('click',close);
 $('extraction-settings-close').addEventListener('click',close);
 dialog.addEventListener('click',event=>{if(event.target===dialog)close()});
}
function initFocusedLanding(){
 const section=$('input-section'),crawl=section?.querySelector('.crawl-settings');
 if(!section||!crawl||section.dataset.focusedLandingReady)return;
 section.dataset.focusedLandingReady='true';
 // Remove the legacy global control; advanced input choices now live beside each input.
 document.getElementById('advanced-input-toggle')?.remove();
 const provider=document.createElement('div');
 provider.className='engine-state field';
 provider.hidden=true;
 provider.innerHTML='<label for="extraction-provider">WEBSITE EXTRACTION PROVIDER</label><select id="extraction-provider"><option value="deterministic" selected>GapScan engine (default)</option><option value="firecrawl">Firecrawl · resilient website extraction</option></select><input id="firecrawl-api-key" type="password" autocomplete="off" spellcheck="false"><a id="firecrawl-key-link" href="https://www.firecrawl.dev/app/api-keys" target="_blank" rel="noreferrer">Open Firecrawl API keys ↗</a>';
 crawl.before(provider);
 initExtractionSettings();
}
function initThemeToggle(){
 const toggle=$('theme-toggle');
 if(!toggle)return;
 const apply=theme=>{const dark=theme==='dark';const value=dark?'dark':'light';document.body.dataset.theme=value;toggle.setAttribute('aria-pressed',String(dark));toggle.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');toggle.title=dark?'Switch to light theme':'Switch to dark theme';toggle.dataset.theme=value;document.documentElement.style.colorScheme=value;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#212121':'#f5f5f7');try{localStorage.setItem('gapscan-theme',value);sessionStorage.setItem('gapscan-theme',value)}catch(error){/* Storage can be unavailable in embedded previews. */}};
 let storedTheme='';try{storedTheme=localStorage.getItem('gapscan-theme')||sessionStorage.getItem('gapscan-theme')||''}catch(error){/* Use the dark default when storage is unavailable. */}
 // Dark is the product's primary workspace theme. A deliberate light-mode
 // choice remains sticky, including when a newly opened page is reloaded.
 apply(storedTheme||'dark');
 toggle.addEventListener('click',()=>apply(document.body.dataset.theme==='dark'?'light':'dark'));
}
function initSidebarToggle(){
 const sidebar=document.querySelector('.sidebar'),toggle=$('sidebar-toggle');
 if(!sidebar||!toggle)return;
 const apply=collapsed=>{
  sidebar.classList.toggle('collapsed',collapsed);
  document.body.classList.toggle('sidebar-collapsed',collapsed);
  toggle.setAttribute('aria-expanded',String(!collapsed));
  toggle.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');
  toggle.title=collapsed?'Expand sidebar':'Collapse sidebar';
 };
 apply(localStorage.getItem('gapscan-sidebar-collapsed')==='true');
 toggle.addEventListener('click',()=>{
  const collapsed=!sidebar.classList.contains('collapsed');
  apply(collapsed);
  localStorage.setItem('gapscan-sidebar-collapsed',String(collapsed));
 });
}
initFocusedLanding();
initThemeToggle();
initSidebarToggle();
hydrateIcons(document);
